import { ACTIONS, currentPlayer, getLegalCards, topCard } from './game-engine/engine.js';
import { COLORS, TYPES } from './game-engine/cards.js';
import { createQuickSession, createTavernMatch, finishRound, restoreSession, standings, startNextRound } from './game-engine/match.js';
import { LocalGameTransport } from './platform/transport.js';
import { ambience, clearMatch, feedback, loadMatch, loadSettings, saveMatch, saveSettings } from './platform/storage.js';
import { chooseBotAction, chooseColor } from './game-ai/bot.js';
import { cardHTML, sigilHTML } from './ui/card.js';

const root=document.querySelector('#app');
const colorHex={red:'#9f2f24',blue:'#244f78',green:'#456b37',yellow:'#b58222'};
const colorName={red:'אדום',blue:'כחול',green:'ירוק',yellow:'צהוב'};
const archetypeName={hunter:'הציידת',bard:'הפייטן',mercenary:'שכיר החרב',wanderer:'הנודד',scholar:'המלומד'};
let settings=loadSettings(),session=null,state=null,transport=null,view='home',sheet=null,hint='',selected=null;
let botTimer=null,eventTimer=null,takiTimer=null,quipTimer=null,roundEndTimer=null,eventBanner=null,quip=null,lastLogLength=0,lastCounts={},lastHands={},lastQuipAt=0,takiRun=0,lastRenderedTopId=null,drawFlights=[],flightId=0,sessionEpoch=0,roundResultVisible=false,incomingCardDelays=new Map(),propRattled=new Set(),screenReaderLine='',captionLine='';
const dialogue={
  hunter:{skip:['צפוי.','חבל.'],penalty:['באמת?','יותר מדי.'],reverse:['משנה מסלול.'],last:['נשאר לי אחד.'],king:['ידעתי ששמרת אותו.']},
  bard:{skip:['יפה.','זה היה מיותר.'],penalty:['איזה נדיב מצדך.','באמת?'],reverse:['לא ראיתי את זה בא.'],last:['אחד אחרון.'],king:['כניסה מרשימה.']},
  mercenary:{skip:['נהדר.','אני אזכור את זה.'],penalty:['באמת?','עוד חשבון לסגור.'],reverse:['אז בכיוון השני.'],last:['נשאר אחד.'],king:['מהלך טוב.']},
  scholar:{skip:['יפה.','נרשם.'],penalty:['לא צפוי.','מעניין.'],reverse:['הכיוון השתנה.'],last:['עוד קלף אחד.'],king:['מהלך מרשים.']}
};

function persist(){if(session)saveMatch(session);}
function setSession(next){sessionEpoch++;clearTimeout(eventTimer);clearTimeout(quipTimer);clearTimeout(roundEndTimer);quip=null;captionLine='';roundResultVisible=next.phase!=='round';session=next;state=session.game;transport?.disconnect();transport=new LocalGameTransport(state);lastLogLength=state.log.length;lastCounts=Object.fromEntries(state.players.map(p=>[p.id,p.hand.length]));lastHands=Object.fromEntries(state.players.map(p=>[p.id,p.hand.map(card=>card.id)]));lastRenderedTopId=null;drawFlights=[];incomingCardDelays.clear();propRattled.clear();eventBanner=null;transport.subscribeToState((nextState,action)=>{state=nextState;session.game=nextState;onState(action);if(nextState.phase==='finished'&&session.phase==='round'){session=finishRound(session);roundResultVisible=false;const epoch=sessionEpoch;roundEndTimer=setTimeout(()=>{if(epoch!==sessionEpoch)return;roundResultVisible=true;feedback('round',settings);persist();render();},settings.reducedMotion?80:400);}persist();render();scheduleGame();});}
function startSession(mode='tavern',saved=null){
  try{setSession(saved?restoreSession(saved):mode==='tavern'?createTavernMatch({seed:Date.now()}):createQuickSession({playerCount:settings.playerCount,seed:Date.now()}));}
  catch{clearMatch();setSession(mode==='tavern'?createTavernMatch({seed:Date.now()}):createQuickSession({playerCount:settings.playerCount,seed:Date.now()}));}
  view='game';sheet=null;eventBanner=null;ambience.start(settings);render();scheduleGame();
}
function submit(action){try{transport.submitAction(action);selected=null;}catch{hint='אי אפשר לשחק את הקלף הזה עכשיו';feedback('invalid',settings);render();setTimeout(()=>{hint='';render();},850);}}
function showEvent(kind,targetId=null,amount=null){clearTimeout(eventTimer);eventBanner={kind,targetId,amount};eventTimer=setTimeout(()=>{eventBanner=null;captionLine='';root.querySelector('.table-event')?.remove();root.querySelector('.direction-engraving')?.classList.remove('lit');root.querySelectorAll('.stop-seal').forEach(node=>node.remove());root.querySelectorAll('.opponent.sealed').forEach(node=>node.classList.remove('sealed'));root.querySelector('.taki-clasp.opening')?.classList.remove('opening');},settings.reducedMotion?60:620);}
function showQuip(player,text,force=false){if(!settings.dialogue||!text||(!force&&Date.now()-lastQuipAt<6500))return;lastQuipAt=Date.now();clearTimeout(quipTimer);quip={player,text};quipTimer=setTimeout(()=>{quip=null;render();},Math.min(3000,1600+text.length*45));}
function botLine(playerId,trigger){const player=state.players.find(p=>p.id===playerId),pool=dialogue[player?.archetype]?.[trigger]||[];return pool[Math.floor(Math.random()*pool.length)];}
function announce(entries){const names=Object.fromEntries(state.players.map(p=>[p.id,p.name]));const stop=entries.find(x=>x.type==='stop'),penalty=entries.find(x=>x.type==='drawPenalty'),draw=entries.find(x=>x.type==='draw'),stack=entries.find(x=>x.type==='plus2'),play=entries.findLast?.(x=>x.type==='play');if(stop)return`התור של ${names[stop.skipped]} דולג`;if(penalty)return`נוספו ${penalty.amount} קלפים ליד של ${names[penalty.playerId]}`;if(draw)return`נוסף קלף ליד של ${names[draw.playerId]}`;if(entries.some(x=>x.type==='reverse'))return'כיוון המשחק התהפך';if(entries.some(x=>x.type==='takiOpened'))return'רצף טאקי נפתח';if(entries.some(x=>x.type==='takiClosed'))return'רצף טאקי נסגר';if(entries.some(x=>x.type==='playAgain'))return`התור ממשיך אצל ${currentPlayer(state).name}`;if(entries.some(x=>x.type==='color'))return`הצבע הפעיל: ${colorName[entries.find(x=>x.type==='color').color]}`;if(stack)return`עונש המשיכה הצטבר ל-${stack.amount}`;if(entries.some(x=>x.type==='win'))return`הסיבוב הסתיים בניצחון של ${names[entries.find(x=>x.type==='win').playerId]}`;if(play){const card=state.discardPile.find(c=>c.id===play.cardId);return`${names[play.playerId]}: ${card?cardLabel(card):'קלף'}`;}return'';}
function winnerLine(player){if(!player)return'';if(player.id==='p0')return'ניצחתם!';return`${player.name} ${['איילה','לידיה'].includes(player.name)?'ניצחה':'ניצח'}!`;}
function queueDraw(playerId,amount){const player=state.players.find(p=>p.id===playerId);if(!player)return;const flight={id:++flightId,playerId,slot:player.kind==='human'?'human':(opponentSlot(player.id)),count:Math.min(amount,6),amount};drawFlights.push(flight);setTimeout(()=>{drawFlights=drawFlights.filter(item=>item.id!==flight.id);root.querySelectorAll(`[data-flight-id="${flight.id}"]`).forEach(node=>node.remove());},settings.reducedMotion?90:600);}
function opponentSlot(playerId){const players=state.players.slice(1,6),layouts={1:['top'],2:['left','right'],3:['left','top','right'],4:['far-left','left','right','far-right'],5:['far-left','left','top','right','far-right']};return (layouts[players.length]||layouts[5])[players.findIndex(p=>p.id===playerId)]||'top';}
function onState(action){
  const entries=state.log.slice(lastLogLength);lastLogLength=state.log.length;
  const latest=entries.at(-1),stop=entries.find(e=>e.type==='stop'),reverse=entries.find(e=>e.type==='reverse'),again=entries.find(e=>e.type==='playAgain'),penalty=entries.find(e=>e.type==='drawPenalty'),color=entries.find(e=>e.type==='color'),closed=entries.find(e=>e.type==='takiClosed'),opened=entries.find(e=>e.type==='takiOpened'),draw=entries.find(e=>e.type==='draw');
  const played=entries.findLast?.(e=>e.type==='play');const playedCard=played?state.discardPile.find(c=>c.id===played.cardId):null;
  const arrived=[];for(const player of state.players){let order=0;const old=new Set(lastHands[player.id]||[]);for(const card of player.hand)if(!old.has(card.id)){incomingCardDelays.set(card.id,{delay:360+Math.min(order++,5)*72,started:performance.now()});arrived.push(card.id);}lastHands[player.id]=player.hand.map(card=>card.id);lastCounts[player.id]=player.hand.length;}
  if(arrived.length){const epoch=sessionEpoch;setTimeout(()=>{if(epoch!==sessionEpoch)return;for(const id of arrived){incomingCardDelays.delete(id);root.querySelector(`[data-card-id="${id}"]`)?.classList.remove('incoming');}},settings.reducedMotion?90:1100);}
  screenReaderLine=announce(entries);captionLine=screenReaderLine;
  for(const e of entries)if(e.type==='draw')queueDraw(e.playerId,e.amount||1);else if(e.type==='drawPenalty')queueDraw(e.playerId,e.amount);
  const stack=entries.find(e=>e.type==='plus2');
  if(stop)showEvent('stop',stop.skipped);else if(closed&&opened)showEvent('takiCycle');else if(closed)showEvent('takiClose');else if(opened)showEvent('takiOpen');else if(reverse)showEvent('reverse');else if(again)showEvent('plus');else if(stack)showEvent('play');else if(penalty)showEvent('penalty',null,penalty.amount);else if(color)showEvent('color');else if(playedCard?.type===TYPES.KING)showEvent('king');else if(entries.length)showEvent('play');
  if(closed&&opened){feedback('takiOpen',settings);setTimeout(()=>feedback('clack',settings),220);}else if(closed)feedback('clack',settings);else if(opened)feedback('takiOpen',settings);else if(stop)feedback('stop',settings);else if(reverse)feedback('reverse',settings);else if(stack||penalty)feedback('penalty',settings);else if(playedCard?.type===TYPES.KING)feedback('king',settings);else if(again)feedback('plus',settings);else if(draw||action.type===ACTIONS.DRAW)feedback('draw',settings);else if(color)feedback('color',settings);else if(entries.length)feedback('play',settings);
  if(penalty?.amount>=6){propRattled.add(penalty.playerId);const epoch=sessionEpoch;setTimeout(()=>{if(epoch!==sessionEpoch)return;propRattled.delete(penalty.playerId);root.querySelector(`[data-player-id="${penalty.playerId}"]`)?.classList.remove('rattled');},520);}
  if(state.taki?.open)takiRun++;if(closed){if(takiRun>=3){const watcher=state.players.find(p=>p.kind==='ai'&&p.id!==closed.playerId);showQuip(watcher?.id,botLine(watcher?.id,'penalty'));}takiRun=0;}
  if(stop)showQuip(stop.skipped,botLine(stop.skipped,'skip'));
  else if(penalty&&penalty.amount>=4)showQuip(penalty.playerId,botLine(penalty.playerId,'penalty'));
  else if(reverse){const speaker=state.players.find(p=>p.kind==='ai');showQuip(speaker?.id,botLine(speaker?.id,'reverse'));}
  else if(playedCard?.type===TYPES.KING){const speaker=state.players.find(p=>p.kind==='ai'&&p.id!==played.playerId);showQuip(speaker?.id,botLine(speaker?.id,'king'));}
}
function delay(){const base=settings.difficulty==='quick'?620:settings.difficulty==='thoughtful'?1350:900;const archetype=currentPlayer(state)?.archetype;return base+(archetype==='hunter'?180:archetype==='bard'?-90:0);}
function scheduleGame(){
  clearTimeout(botTimer);clearTimeout(takiTimer);
  if(!state||session.phase!=='round'||state.phase==='finished')return;
  const active=currentPlayer(state);
  if(active.kind==='human'&&state.taki?.open&&state.taki.ownerId===active.id){takiTimer=setTimeout(()=>submit({type:ACTIONS.END_TURN,playerId:active.id}),settings.reducedMotion?500:1450);return;}
  if(active.kind!=='ai')return;
  const playerId=active.id,epoch=sessionEpoch,scheduledTurn=state.turn;
  console.info('AI turn scheduled',{playerId,epoch,scheduledTurn});
  botTimer=setTimeout(()=>{
    console.info('AI timer fired',{playerId,epoch,currentEpoch:sessionEpoch,scheduledTurn,currentTurn:state?.turn,phase:session?.phase,gamePhase:state?.phase});
    if(epoch!==sessionEpoch||!state||session.phase!=='round'||state.phase==='finished'){console.warn('AI timer stopped by session guard');return;}
    const current=currentPlayer(state);
    if(current.id!==playerId||current.kind!=='ai'||state.turn!==scheduledTurn){console.warn('AI timer stopped by turn guard',{currentId:current.id,kind:current.kind,currentTurn:state.turn});return;}
    try{transport.submitAction(chooseBotAction(state));}
    catch(error){
      console.error('AI turn action failed',error);
      if(currentPlayer(state).id===playerId&&state.phase==='playing'){
        try{transport.submitAction({type:ACTIONS.DRAW,playerId});}
        catch(fallbackError){console.error('AI fallback draw failed',fallbackError);}
      }
      if(state.phase!=='finished'&&currentPlayer(state).kind==='ai')scheduleGame();
    }
  },delay());
}

function homeHTML(){
  const saved=loadMatch();let savedSession=null;try{savedSession=saved?restoreSession(saved):null;}catch{}
  const resumable=savedSession&&savedSession.phase!=='matchFinished';
  return `<main class="app-shell elder-home ${settings.reducedMotion?'reduced-motion':''}" dir="rtl"><div class="ambient-scene" aria-hidden="true"><i class="fire-glow"></i><i class="candle-glow"></i><i class="room-haze"></i></div><section class="home-scene"><div class="home-title">${sigilHTML('title-sigil')}<h1><span>ELDER</span><b>TAKI</b></h1></div><div class="table-choices">${resumable?'<button class="resume-marker" data-resume>חזרה לשולחן</button>':''}<button class="mode-object tavern-mode" data-tavern><span class="coin-stack"><i></i><i></i><i></i><i></i><i></i></span><span><b>משחק פונדק</b><small><bdi>5</bdi> סיבובים · <bdi>4</bdi> שחקנים</small></span></button><button class="mode-object quick-mode" data-open="quick"><span class="single-card">${sigilHTML()}</span><b>משחק מהיר</b></button><div class="table-tools"><button data-open="rules"><i class="folded-rules"></i><span>חוקים</span></button><button data-open="settings"><i class="brass-cog"></i><span>הגדרות</span></button></div></div></section>${sheetHTML()}</main>`;
}
function scoreBoardHTML(){if(session.mode!=='tavern')return'';const latest=session.results.at(-1),scored=roundResultVisible&&session.phase!=='round'?latest?.winnerId:null;return `<aside class="score-slate" aria-label="ניקוד מצטבר">${standings(session).map(p=>{const displayScore=!roundResultVisible&&latest?.winnerId===p.id?p.score-latest.points:p.score;return `<div class="score-row ${p.id===scored?'scored':''}"><span>${p.name}</span><bdi>${displayScore}</bdi></div>`;}).join('')}</aside>`;}
function propsHTML(player){const motifs={hunter:['<path d="M12 17h36l-3 33H15zM48 23h8v19h-8M17 17l4-7h18l4 7"/><path d="M16 24h31"/>','<path d="M10 52 34 14l13-8-6 15-24 34z"/><path d="m8 47 10 7-5 7-10-7zM28 31l8 5"/>'],bard:['<path d="M20 9h24l-4 19q-2 8-8 9-7-1-8-9zM32 37v14m-9 2h18"/>','<circle cx="17" cy="29" r="6"/><circle cx="29" cy="25" r="6"/><circle cx="25" cy="38" r="6"/><circle cx="39" cy="35" r="6"/>'],mercenary:['<path d="M12 16h36v34H12zM48 23h9v20h-9M16 11h28v7H16z"/><path d="M16 25h28"/>','<path d="M8 32q12-19 30-2-10 19-30 2m25-5 21 12-6 8-18-13"/>'],wanderer:['<path d="M16 25h33l-4 20q-3 7-12 7-9 0-13-7zM49 30h8q8 3 0 14h-8M17 55h37"/><path d="M22 22q8-8 18 0"/>','<path d="M7 36q12-21 30-2-11 19-30 2m26-4 20 12-5 7-18-13"/>'],scholar:['<path d="M15 24h34l-4 21q-2 7-13 7t-13-7zM49 29h8q7 3 0 13h-8M16 55h36"/><path d="M22 20q8-12 17 0"/>','<path d="M10 12h39v42H10zM18 22h23M18 29h23M18 36h16"/>']};const [drink,snack]=motifs[player.archetype]||motifs.wanderer;return `<span class="seat-props ${player.archetype||'wanderer'}" aria-hidden="true"><i class="drink-prop"><svg viewBox="0 0 64 64">${drink}</svg></i><i class="snack-prop"><svg viewBox="0 0 64 64">${snack}</svg></i></span>`;}
function opponentHTML(player,slot){const active=currentPlayer(state).id===player.id,stopped=eventBanner?.kind==='stop'&&eventBanner.targetId===player.id,count=Math.min(10,player.hand.length),backs=Array.from({length:count},(_,i)=>`<i style="--offset:${i-(count-1)/2}"><span>${sigilHTML()}</span></i>`).join(''),winning=session.phase!=='round'&&session.results.at(-1)?.winnerId===player.id;return `<div class="opponent seat-${slot} ${active?'active':''} ${stopped?'sealed':''} ${propRattled.has(player.id)?'rattled':''} ${winning?'winner-seat':''} ${player.hand.length===1?'last-card':''}" data-player-id="${player.id}" role="group" aria-label="${active?`התור עכשיו אצל ${player.name}`:`${player.name}, יד נסתרת`}"><div class="seat-marker"><i class="house-pin ${player.house||''}"></i><span>${player.name}</span><small>${archetypeName[player.archetype]||'יריב'}</small><b><i></i><bdi>${player.hand.length}</bdi></b></div><div class="opponent-fan">${backs}</div>${propsHTML(player)}${stopped?'<span class="stop-seal" aria-hidden="true"><svg viewBox="0 0 64 64"><path d="M24 49 12 30c-3-6 4-9 8-4l5 6V15c0-6 8-6 8 0v15-18c0-6 8-6 8 0v18-13c0-6 8-6 8 0v16-7c0-6 8-6 8 0v12c0 12-8 20-20 20-8 0-13-3-17-9z"/></svg></span>':''}${quip?.player===player.id?`<div class="speech" role="status">${quip.text}</div>`:''}</div>`;}
function opponentSeats(players){const layouts={1:['top'],2:['left','right'],3:['left','top','right'],4:['far-left','left','right','far-right'],5:['far-left','left','top','right','far-right']};return players.map((p,i)=>opponentHTML(p,(layouts[players.length]||layouts[5])[i]||'top')).join('');}
function statusHTML(){const bits=[];if(state.activePenalty)bits.push(`<span class="penalty-token" aria-label="משיכת ${state.activePenalty.amount} קלפים"><bdi>+${state.activePenalty.amount}</bdi><i></i></span>`);if(state.taki?.open)bits.push(`<span class="taki-clasp open ${eventBanner?.kind==='takiOpen'?'opening':''}" style="--taki-color:${colorHex[state.taki.color]}" aria-label="רצף טאקי פעיל"><i class="clasp-jaw left"></i><i class="clasp-jaw right"></i><b></b></span>`);if(state.freePlay)bits.push('<span class="extra-turn-token" aria-label="תור נוסף">+</span>');return bits.join('');}
function choiceHTML(){if(state.awaitingColor?.playerId!=='p0')return'';return `<div class="color-choice" role="dialog" aria-label="בחירת צבע"><div class="gem-ring"><span>בחרו צבע</span>${COLORS.map(c=>`<button class="gem ${c}" data-color="${c}" aria-label="${colorName[c]}"><i></i></button>`).join('')}</div></div>`;}
function eventHTML(){const caption=settings.captions&&captionLine?`<span class="event-caption">${captionLine}</span>`:'';if(!eventBanner)return caption?`<div class="table-event caption-only"><span class="event-caption">${captionLine}</span></div>`:'';const clasp=['takiClose','takiCycle'].includes(eventBanner.kind)?`<span class="event-clasp ${eventBanner.kind==='takiCycle'?'cycle':'closing'}" aria-hidden="true"><i class="clasp-jaw left"></i><i class="clasp-jaw right"></i><b></b></span>`:'';return `<div class="table-event ${eventBanner.kind} ${caption?'with-caption':''}">${clasp}<i aria-hidden="true"></i><b aria-hidden="true">${eventBanner.amount?`+${eventBanner.amount}`:''}</b>${caption}</div>`;}
function flightsHTML(){return drawFlights.map(f=>Array.from({length:f.count},(_,i)=>`<span class="card-flight to-${f.slot}" data-flight-id="${f.id}" style="--flight-delay:${i*(f.count>5?42:72)}ms;--flight-index:${i}" aria-hidden="true"></span>`).join('')).join('');}
function roundMarkerHTML(){if(session.mode!=='tavern')return'<div class="round-marker">משחק מהיר</div>';return `<div class="round-marker">${session.suddenDeath?'יד מכרעת':`סיבוב <bdi>${session.round}</bdi> מתוך <bdi>${session.totalRounds}</bdi>`}</div>`;}
function gameHTML(){
  const human=state.players[0],active=currentPlayer(state),isHumanTurn=session.phase==='round'&&active.id===human.id&&!state.awaitingColor,legal=new Set(isHumanTurn?getLegalCards(state,human.id).map(c=>c.id):[]),shown=human.hand.slice(0,13),more=human.hand.length-shown.length,top=topCard(state);
  const turnHint=hint||(settings.captions&&isHumanTurn?'התור שלכם':'');
  const under=state.discardPile.slice(-4,-1),fresh=top.id!==lastRenderedTopId;lastRenderedTopId=top.id;
  return `<main class="app-shell table-shell ${settings.reducedMotion?'reduced-motion':''}" dir="rtl" style="--active:${colorHex[state.activeColor]||'#b78b45'}"><div class="ambient-scene" aria-hidden="true"><i class="fire-glow"></i><i class="candle-glow"></i><i class="room-haze"></i></div><section class="game ${isHumanTurn?'human-turn':'waiting'}"><header class="game-head"><button class="rune-menu" data-open="pause" aria-label="תפריט והשהיה"><i></i><i></i><i></i></button>${roundMarkerHTML()}${scoreBoardHTML()}</header><div class="board"><div class="direction-engraving ${state.direction<0?'counter':''} ${eventBanner?.kind==='reverse'?'lit':''} ${state.taki?.open?'taki-lit':''}">${sigilHTML('table-sigil')}<span class="house-node red ${state.activeColor==='red'?'on':''}"></span><span class="house-node blue ${state.activeColor==='blue'?'on':''}"></span><span class="house-node green ${state.activeColor==='green'?'on':''}"></span><span class="house-node yellow ${state.activeColor==='yellow'?'on':''}"></span></div><div class="opponents">${opponentSeats(state.players.slice(1,6))}</div><div class="center"><div class="status-stack">${statusHTML()}</div><button class="pile draw-pile" data-draw aria-label="משיכת קלף. ${state.drawPile.length} קלפים נותרו" style="--deck-depth:${Math.min(8,Math.ceil(state.drawPile.length/15))}px"><span class="back-sigil">${sigilHTML()}</span><span class="deck-count"><bdi>${state.drawPile.length}</bdi></span></button><div class="pile discard ${fresh?'fresh':''}" style="--pile-turn:${((state.discardPile.length%7)-3)*.7}deg" aria-label="הקלף המוביל. הצבע הפעיל: ${colorName[state.activeColor]||'חופשי'}"><div class="discard-under">${under.map((card,i)=>`<span class="under under-${i}">${cardHTML(card)}</span>`).join('')}</div>${cardHTML(top)}<span class="active-stone ${state.activeColor||'wild'}"></span></div>${eventHTML()}</div>${flightsHTML()}<span class="sr-only" aria-live="polite" aria-atomic="true">${screenReaderLine}</span></div><footer class="hand-area ${isHumanTurn?'your-active':''}"><div class="turn-whisper">${turnHint}</div><div class="hand ${state.taki?.open?'taki-active':''}">${shown.map((card,i)=>{const incoming=incomingCardDelays.get(card.id);return cardHTML(card,{legal:isHumanTurn&&legal.has(card.id),selected:selected===card.id,incoming:!!incoming,arrivalDelay:incoming?incoming.delay-(performance.now()-incoming.started):0,index:i,total:shown.length});}).join('')}</div>${more>0?`<span class="more-cards">+${more}</span>`:''}${quip?.player==='p0'?`<div class="human-quip">${quip.text}</div>`:''}</footer></section>${choiceHTML()}${summaryHTML()}${sheetHTML()}</main>`;
}
function summaryHTML(){
  if(!session||session.phase==='round'||(!roundResultVisible&&session.phase!=='round'))return'';
  if(session.mode==='quick'){const winner=state.players.find(p=>p.id===session.championId);return `<div class="result-wrap"><article class="tally-board"><small>סוף הסיבוב</small><h2>${winnerLine(winner)}</h2><div class="result-actions"><button class="leather-button primary" data-quick>לסיבוב נוסף</button><button class="text-link" data-home>לצאת מהשולחן</button></div></article></div>`;}
  if(session.phase==='matchFinished'){const champion=session.roster.find(p=>p.id===session.championId);return `<div class="result-wrap"><article class="tally-board champion">${sigilHTML('result-sigil')}<small>אלוף הפונדק</small><h2>${champion?.id==='p0'?'אתם':champion?.name}</h2><div class="final-standing">${standings(session).map((p,i)=>`<div><b><bdi>${i+1}</bdi></b><span>${p.name}</span><strong><bdi>${p.score}</bdi></strong></div>`).join('')}</div><div class="result-actions"><button class="leather-button primary" data-tavern>ערב נוסף</button><button class="text-link" data-home>לעזוב את השולחן</button></div></article></div>`;}
  const result=session.results.at(-1),winner=session.roster.find(p=>p.id===result.winnerId),losers=session.roster.filter(p=>p.id!==result.winnerId),equation=losers.map(p=>result.remaining[p.id]).join(' + ');
  return `<div class="result-wrap table-result"><article class="tally-board round-tally"><small>${session.suddenDeath?'יד מכרעת':`סיבוב <bdi>${result.round}</bdi>`}</small><h2>${winnerLine(winner)}</h2><div class="round-count">${losers.map((p,i)=>`<span style="--token-order:${i}"><small>${p.name}</small><b><bdi>${result.remaining[p.id]}</bdi></b></span>`).join('')}</div><div class="coin-total"><span dir="ltr">${equation}</span><strong><bdi>+${result.points}</bdi></strong></div><div class="result-actions"><button class="leather-button primary" data-next>${session.suddenDeath?'ליד המכרעת':'לסיבוב הבא'}</button><button class="text-link" data-home>לשמור ולצאת</button></div></article></div>`;
}
function sheetHTML(){
  if(!sheet)return'';
  if(sheet==='quick')return `<div class="sheet-wrap"><article class="tavern-sheet"><h2>משחק מהיר</h2><p>יד אחת, בלי ניקוד מצטבר.</p><label>מספר שחקנים</label><div class="segmented">${[2,3,4,6,8,10].map(n=>`<button data-players="${n}" class="${settings.playerCount===n?'on':''}">${n}</button>`).join('')}</div><button class="parchment-button primary" data-quick>להתחיל</button><button class="text-link" data-close-sheet>חזרה</button></article></div>`;
  if(sheet==='rules')return `<div class="sheet-wrap"><article class="tavern-sheet rules"><h2>חוקי Elder Taki</h2><p>התאימו צבע, מספר או סמל. אם משכתם קלף, הוא יחכה לתור הבא. הראשון שמרוקן את היד מנצח.</p><h3>TAKI</h3><p>TAKI פותח רצף בצבע אחד עבור מי שהניח אותו. הרצף נסגר מעצמו כשמפסיקים או כשאין המשך חוקי. רק הפקודה האחרונה ברצף פועלת.</p><h3>משחק פונדק</h3><p>חמישה סיבובים מול שלושה יריבים. המנצח בכל יד מקבל נקודה על כל קלף שנותר בידי האחרים. שוויון אחרי הסיבוב החמישי מוביל ליד מכרעת.</p><h3>הקלפים העתיקים</h3><p><b>עצור</b> מדלג, <b>שנה כיוון</b> הופך את הסדר, <b>פלוס</b> מעניק מהלך נוסף, <b>2+</b> מצטבר, <b>שנה צבע</b> בוחר בית, <b>סופר TAKI</b> יורש את הצבע ו<b>מלך</b> מבטל מגבלה.</p><button class="parchment-button" data-close-sheet>הבנתי</button></article></div>`;
  return `<div class="sheet-wrap"><article class="tavern-sheet"><h2>${sheet==='pause'?'המשחק מושהה':'הגדרות'}</h2>${toggleRow('צלילי משחק','sound')}${toggleRow('אווירת פונדק','ambience')}${toggleRow('דברי יריבים','dialogue')}${toggleRow('כתוביות לאירועי משחק','captions')}${toggleRow('רטט','haptics')}${toggleRow('צמצום תנועה','reducedMotion')}<button class="parchment-button" data-close-sheet>${sheet==='pause'?'לחזור לשולחן':'סיום'}</button>${sheet==='pause'?'<button class="text-link" data-home>שמירה ויציאה</button>':''}</article></div>`;
}
function toggleRow(label,key){return `<div class="toggle-row"><label>${label}</label><button class="iron-switch ${settings[key]?'on':''}" data-toggle="${key}" aria-pressed="${settings[key]}"><i></i></button></div>`;}

function render(){root.innerHTML=view==='home'?homeHTML():gameHTML();bind();}
function goHome(){clearTimeout(botTimer);clearTimeout(takiTimer);clearTimeout(eventTimer);clearTimeout(roundEndTimer);ambience.stop();view='home';sheet=null;render();}
function bind(){
  root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{sheet=b.dataset.open;render();});
  root.querySelectorAll('[data-close-sheet]').forEach(b=>b.onclick=()=>{sheet=null;render();});
  root.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{settings[b.dataset.toggle]=!settings[b.dataset.toggle];saveSettings(settings);if(b.dataset.toggle==='ambience'||b.dataset.toggle==='sound'){ambience.stop();ambience.start(settings);}render();});
  root.querySelectorAll('[data-players]').forEach(b=>b.onclick=()=>{settings.playerCount=+b.dataset.players;saveSettings(settings);render();});
  root.querySelector('[data-tavern]')?.addEventListener('click',()=>{clearMatch();startSession('tavern');});
  root.querySelector('[data-quick]')?.addEventListener('click',()=>{clearMatch();startSession('quick');});
  root.querySelector('[data-resume]')?.addEventListener('click',()=>startSession('tavern',loadMatch()));
  root.querySelector('[data-next]')?.addEventListener('click',()=>{feedback('shuffle',settings);setSession(startNextRound(session));render();scheduleGame();});
  root.querySelectorAll('[data-home]').forEach(b=>b.onclick=goHome);
  root.querySelector('[data-draw]')?.addEventListener('click',()=>{if(currentPlayer(state).id==='p0'&&!state.taki?.open)submit({type:ACTIONS.DRAW,playerId:'p0'});});
  root.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>submit({type:ACTIONS.CHOOSE_COLOR,playerId:'p0',color:b.dataset.color}));
  root.querySelectorAll('.hand .card.legal').forEach(card=>{let startY=0,moved=false;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();submit({type:ACTIONS.PLAY,playerId:'p0',cardId:card.dataset.cardId});}};card.onpointerdown=e=>{startY=e.clientY;moved=false;card.setPointerCapture(e.pointerId);selected=card.dataset.cardId;card.classList.add('selected');};card.onpointermove=e=>{if(!card.hasPointerCapture(e.pointerId))return;const dy=e.clientY-startY;if(Math.abs(dy)>7)moved=true;card.style.transform=`translateY(${Math.min(0,dy)}px) rotate(0deg)`;};card.onpointerup=e=>{const dy=e.clientY-startY;card.releasePointerCapture(e.pointerId);if(dy<-58||!moved)submit({type:ACTIONS.PLAY,playerId:'p0',cardId:card.dataset.cardId});else render();};});
}

if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;try{void Promise.resolve(context.registerTool({name:'read_game_state',title:'Read Elder Taki game',description:'Read the current Elder Taki match status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return session?{mode:session.mode,phase:session.phase,round:session.round,totalRounds:session.totalRounds,suddenDeath:session.suddenDeath,scores:session.scores,currentPlayer:currentPlayer(state).name,activeColor:state.activeColor,humanCardCount:state.players[0].hand.length,opponents:state.players.slice(1).map(p=>({name:p.name,cardCount:p.hand.length}))}:{phase:'home'};}})).catch(()=>{});}catch{}}
registerWebMCP();render();
